#!/usr/bin/env python3
"""Build complete registered scope-owned vector signal metadata inventory."""
import argparse
import json
from pathlib import Path
import subprocess
import build_display_association as base
from ttl7406_probe import sha


def build(archive,out,bison,jobs):
    runtime,display=base.RUNTIME_PATCHES,base.DISPLAY_PATCHES
    try:
        base.RUNTIME_PATCHES=runtime+('icarus-single-display-runtime.patch','icarus-executing-wrapper-link.patch',
                                     'icarus-executing-event.patch','icarus-value-callback-observer.patch','icarus-startup-callback-observer.patch','icarus-assignment-observer.patch','icarus-primitive-observer.patch','icarus-island-observer.patch','icarus-island-queue.patch','icarus-island-filter.patch','icarus-thread-observer.patch','icarus-thread-queue.patch','icarus-wait-observer.patch','icarus-thread-lifecycle.patch','icarus-code-binding.patch','icarus-scope-observer.patch','icarus-code-operands.patch','icarus-array-observer.patch','icarus-array-compact.patch','icarus-net-observer.patch','icarus-net-delta.patch','icarus-net-types.patch','icarus-wire-observer.patch','icarus-wire-delta.patch','icarus-signal-observer.patch','icarus-signal-delta.patch','icarus-mux-observer.patch','icarus-mux-delta.patch','icarus-gate-observer.patch','icarus-gate-delta.patch','icarus-arithmetic-observer.patch','icarus-arithmetic-delta.patch','icarus-reduction-observer.patch','icarus-reduction-delta.patch','icarus-wire-raw.patch','icarus-wire-raw-delta.patch','icarus-concat-observer.patch','icarus-concat-delta.patch','icarus-resolver-observer.patch','icarus-resolver-delta.patch','icarus-island-raw.patch','icarus-island-raw-delta.patch','icarus-assignment-raw.patch','icarus-assignment-dispatch.patch','icarus-callback-lists.patch','icarus-callback-words.patch','icarus-callback-delta.patch','icarus-signal-handles.patch','icarus-callback-signal-links.patch','icarus-typed-signal-faults.patch','icarus-signal-scope-scan.patch','icarus-scope-admission.patch','icarus-scope-metadata.patch','icarus-scope-metadata-bindings.patch','icarus-scope-metadata-compact.patch','icarus-scope-metadata-faults.patch','icarus-port-payload.patch','icarus-port-payload-faults.patch','icarus-scope-signals.patch','icarus-scope-signal-faults.patch','icarus-parameter-payload.patch','icarus-parameter-faults.patch','icarus-memory-metadata.patch','icarus-array-admission.patch')
        base.DISPLAY_PATCHES=display+('icarus-single-display-module.patch',)
        base.build(archive,out,bison,jobs)
    finally:
        base.RUNTIME_PATCHES,base.DISPLAY_PATCHES=runtime,display
    exports=subprocess.check_output(['nm','-g',str(out/'vvp/libvvp.so')],text=True)
    for symbol in ('robotron_vvp_array_storage_validate','robotron_vvp_array_storage_toggle','robotron_vvp_memory_metadata_inventory','robotron_vvp_memory_owners','robotron_vvp_parameter_toggle','robotron_vvp_parameter_inventory','robotron_vvp_parameter_owners','robotron_vvp_scope_signal_toggle','robotron_vvp_scope_signal_inventory','robotron_vvp_scope_object_owners','robotron_vvp_port_payload_toggle','robotron_vvp_port_payload_inventory','robotron_vvp_scope_metadata_toggle','robotron_vvp_scope_metadata_compact_inventory','robotron_vvp_scope_metadata_reference_compact_inventory','robotron_vvp_scope_metadata_reference_inventory','robotron_vvp_scope_metadata_inventory','robotron_vvp_signal_handle_reference_inventory','robotron_vvp_callback_signal_reference_inventory','robotron_vvp_signal_handle_toggle','robotron_vvp_callback_signal_inventory','robotron_vvp_signal_handle_admit','robotron_vvp_signal_handle_inventory','robotron_vvp_callback_list_reference','robotron_vvp_callback_list_delta_inventory','robotron_vvp_callback_word_toggle','robotron_vvp_callback_list_inventory','robotron_vvp_callback_list_admit','robotron_vvp_assignment_raw_inventory','robotron_vvp_assignment_raw_toggle','robotron_vvp_island_inventory','robotron_vvp_island_toggle','robotron_vvp_island_queue_inventory','robotron_vvp_island_queue_toggle','robotron_vvp_island_filter_inventory','robotron_vvp_island_filter_toggle','robotron_vvp_thread_inventory','robotron_vvp_thread_toggle','robotron_vvp_thread_compact_inventory','robotron_vvp_thread_queue_inventory','robotron_vvp_thread_queue_toggle','robotron_vvp_wait_inventory','robotron_vvp_wait_toggle','robotron_vvp_thread_code_inventory','robotron_vvp_code_identity','robotron_vvp_scope_inventory','robotron_vvp_scope_toggle','robotron_vvp_code_operand_reference','robotron_vvp_code_operand_inventory','robotron_vvp_code_operand_toggle','robotron_vvp_array_inventory','robotron_vvp_array_toggle','robotron_vvp_array_compact_inventory','robotron_vvp_net_inventory','robotron_vvp_net_toggle','robotron_vvp_net_reference','robotron_vvp_net_delta_inventory','robotron_vvp_net_types','robotron_vvp_wire_inventory','robotron_vvp_wire_toggle','robotron_vvp_wire_reference','robotron_vvp_wire_delta_inventory','robotron_vvp_signal_inventory','robotron_vvp_signal_toggle','robotron_vvp_signal_reference','robotron_vvp_signal_delta_inventory','robotron_vvp_mux_inventory','robotron_vvp_mux_toggle','robotron_vvp_mux_queue','robotron_vvp_mux_reference','robotron_vvp_mux_delta_inventory','robotron_vvp_gate_inventory','robotron_vvp_gate_toggle','robotron_vvp_gate_reference','robotron_vvp_gate_delta_inventory','robotron_vvp_arithmetic_inventory','robotron_vvp_arithmetic_toggle','robotron_vvp_arithmetic_reference','robotron_vvp_arithmetic_delta_inventory','robotron_vvp_reduction_inventory','robotron_vvp_reduction_toggle','robotron_vvp_reduction_reference','robotron_vvp_reduction_delta_inventory','robotron_vvp_wire_raw_inventory','robotron_vvp_wire_raw_toggle','robotron_vvp_wire_raw_reference','robotron_vvp_wire_raw_delta_inventory','robotron_vvp_concat_inventory','robotron_vvp_concat_toggle','robotron_vvp_concat_reference','robotron_vvp_concat_delta_inventory','robotron_vvp_resolver_inventory','robotron_vvp_resolver_toggle','robotron_vvp_resolver_reference','robotron_vvp_resolver_delta_inventory','robotron_vvp_island_raw_inventory','robotron_vvp_island_raw_toggle','robotron_vvp_island_raw_reference','robotron_vvp_island_raw_delta_inventory'):
        if symbol not in exports:raise ValueError('Missing primitive API')
    path=out/'build.json';r=json.loads(path.read_text())
    r['sources'][Path(__file__).name]=sha(Path(__file__))
    r['outputs'].update({n:sha(out/n) for n in ('vvp/vpi_priv.h','vvp/vvp_vpi_callback.h')})
    for name in ('resolv.h','resolv.cc','concat.h','concat.cc','reduce.cc','arith.h','arith.cc','schedule.cc','schedule.h','logic.cc','logic.h','part.cc','part.h','vvp_island.cc','vvp_island.h','island_tran.cc','vvp_net.h','vvp_net_sig.h','vvp_net_sig.cc','vthread.cc','event.h','event.cc','codes.cc','codes.h','vpi_scope.cc','compile.cc','array.cc','array_common.cc','array_common.h','vvp_net.cc','vpi_callback.cc','vpi_signal.cc','vpi_const.cc'):r['outputs']['vvp/'+name]=sha(out/'vvp'/name)
    r['scope']='Guarded scope/memory admission precedes array traversal casts. Registered exact static four-state storage validates allocation, dimensions, cell base and wide-word pointers before observation; constructors/destructors and legitimate writes maintain the registry. Lazy word caches and read-port head admission remain separate.'
    path.write_text(json.dumps(r,indent=2)+'\n')


if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__)
    for n in ('archive','out','bison'):p.add_argument('--'+n,type=Path,required=True)
    p.add_argument('--jobs',type=int,default=2)
    a=p.parse_args();build(a.archive,a.out,a.bison,a.jobs)
